def rpn_eval(expression: str) -> float:
    """
    Evaluates a Reverse Polish Notation (postfix) arithmetic expression.

    Args:
        expression: A space-separated string of tokens

    Returns:
        The final numeric result as a float

    Raises:
        ValueError: If the expression is malformed or invalid
    """
    if not expression.strip():
        raise ValueError("Empty expression")

    tokens = expression.split()
    stack = []

    for token in tokens:
        if token in ['+', '-', '*', '/']:
            if len(stack) < 2:
                raise ValueError(f"Not enough operands for operator '{token}'")

            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                result = a / b

            stack.append(result)
        else:
            try:
                # Try to parse as float
                num = float(token)
                stack.append(num)
            except ValueError:
                raise ValueError(f"Unknown token: '{token}'")

    if len(stack) != 1:
        raise ValueError("Invalid expression: leftover operands")

    return stack[0]

